//! T163 uses the same tracked sources as the corpus runner. Expected results
//! are arithmetic constants and specified traps, never generated by the VM.
use std::sync::{
    Arc,
    atomic::{AtomicUsize, Ordering},
};
use wtime_runtime::{Config, Engine, External, Instance, Linker, RunOutcome, Store, Value};
use wtime_types::{ErrorKind, FuncType, TypeIdx};

fn modules(source: &str) -> Vec<Vec<u8>> {
    let buffer = wast::parser::ParseBuffer::new(source).unwrap();
    let mut script = wast::parser::parse::<wast::Wast<'_>>(&buffer).unwrap();
    script
        .directives
        .iter_mut()
        .filter_map(|d| match d {
            wast::WastDirective::Module(module) => Some(module.encode().unwrap()),
            _ => None,
        })
        .collect()
}
fn call(store: &mut Store, instance: &Instance, name: &str) -> wtime_types::Result<RunOutcome> {
    let External::Func(f) = instance.export(store, name)? else {
        panic!("expected function")
    };
    store.invoke(f, &[])
}
#[test]
fn t163_case_01() {
    let bytes = modules(include_str!(
        "../../../tests/fixtures/interactions/captured-descriptor.wast"
    ));
    let engine = Engine::new(Config::default()).unwrap();
    let module = engine.compile(&bytes[1]).unwrap();
    let mut store = Store::new(&engine);
    let collections = Arc::new(AtomicUsize::new(0));
    let observed = collections.clone();
    let collector = store
        .create_host_func_with_caller(FuncType::default(), move |caller, _| {
            assert!(
                caller.collect()?.live >= 3,
                "descriptor, object and suspended segment must survive"
            );
            observed.fetch_add(1, Ordering::SeqCst);
            Ok(vec![])
        })
        .unwrap();
    let mut linker = Linker::new(&engine);
    linker
        .define("env", "collect", External::Func(collector))
        .unwrap();
    let instance = linker.instantiate(&mut store, &module).unwrap();
    assert_eq!(
        call(&mut store, &instance, "run").unwrap(),
        RunOutcome::Returned(vec![Value::I32(77)])
    );
    assert_eq!(collections.load(Ordering::SeqCst), 1);
    assert_eq!(
        store.collect().unwrap().live,
        0,
        "consumed segment releases described object"
    );
    assert_eq!(
        call(&mut store, &instance, "null-descriptor")
            .unwrap_err()
            .kind,
        ErrorKind::Trap
    );
}
#[test]
fn t163_case_02() {
    let bytes = modules(include_str!(
        "../../../tests/fixtures/interactions/exact-compact.wast"
    ));
    let engine = Engine::new(Config::default()).unwrap();
    let consumer = engine.compile(&bytes[1]).unwrap();
    for (provider_index, accepted) in [(0, true), (2, false)] {
        let mut store = Store::new(&engine);
        let provider = engine.compile(&bytes[provider_index]).unwrap();
        let mut linker = Linker::new(&engine);
        let instance = linker.instantiate(&mut store, &provider).unwrap();
        for name in ["a", "b"] {
            linker
                .define("provider", name, instance.export(&store, name).unwrap())
                .unwrap();
        }
        let result = linker.instantiate(&mut store, &consumer);
        if accepted {
            assert_eq!(
                call(&mut store, &result.unwrap(), "sum").unwrap(),
                RunOutcome::Returned(vec![Value::I32(42)])
            );
        } else {
            assert_eq!(result.unwrap_err().kind, ErrorKind::Link);
        }
    }
    // A host callback has the actual declared module type, so exact imports
    // cannot relabel a proper subtype as its requested supertype.
    for (provider_index, declared_type, accepted) in [(0, 0, true), (2, 1, false)] {
        let mut store = Store::new(&engine);
        let provider = engine.compile(&bytes[provider_index]).unwrap();
        let mut linker = Linker::new(&engine);
        for (name, value) in [("a", 20), ("b", 22)] {
            let function = store
                .create_module_host_func(&provider, TypeIdx(declared_type), move |_, _| {
                    Ok(RunOutcome::Returned(vec![Value::I32(value)]))
                })
                .unwrap();
            linker
                .define("provider", name, External::Func(function))
                .unwrap();
        }
        let result = linker.instantiate(&mut store, &consumer);
        if accepted {
            assert_eq!(
                call(&mut store, &result.unwrap(), "sum").unwrap(),
                RunOutcome::Returned(vec![Value::I32(42)])
            );
        } else {
            assert_eq!(result.unwrap_err().kind, ErrorKind::Link);
        }
    }
    let mut config = Config::default();
    config.features.compact_imports = false;
    assert_eq!(
        Engine::new(config)
            .unwrap()
            .compile(&bytes[1])
            .unwrap_err()
            .kind,
        ErrorKind::DisabledFeature
    );
}
#[test]
fn t163_case_03() {
    let bytes = modules(include_str!(
        "../../../tests/fixtures/interactions/shared-wide-simd.wast"
    ));
    let engine = Engine::new(Config::default()).unwrap();
    let module = engine.compile(&bytes[0]).unwrap();
    let mut store = Store::new(&engine);
    let instance = Linker::new(&engine)
        .instantiate(&mut store, &module)
        .unwrap();
    assert_eq!(
        call(&mut store, &instance, "run").unwrap(),
        RunOutcome::Returned(vec![Value::I32(15)])
    );
    let External::Memory(memory) = instance.export(&store, "shared").unwrap() else {
        panic!("expected memory")
    };
    let shared = store.share_memory(memory).unwrap();
    std::thread::spawn(move || {
        let mut other = Store::new(&engine);
        let memory = other.import_shared_memory(&shared).unwrap();
        other
            .write_memory(memory, 16, &100u32.to_le_bytes())
            .unwrap();
    })
    .join()
    .unwrap();
    assert_eq!(
        call(&mut store, &instance, "read").unwrap(),
        RunOutcome::Returned(vec![Value::I32(100)])
    );
    assert_eq!(
        call(&mut store, &instance, "dispatch").unwrap(),
        RunOutcome::Returned(vec![Value::I32(21)])
    );
    for name in ["unaligned", "bounds", "table-bounds"] {
        assert_eq!(
            call(&mut store, &instance, name).unwrap_err().kind,
            ErrorKind::Trap
        );
    }
    let mut config = Config::default();
    config.features.custom_page_sizes = false;
    assert_eq!(
        Engine::new(config)
            .unwrap()
            .compile(&bytes[0])
            .unwrap_err()
            .kind,
        ErrorKind::DisabledFeature
    );
}

#[test]
fn t141_actual_multiple_bind_is_lazy_ordered_and_consuming() {
    let source = r#"(module
      (type $f0 (func (param i32 i32) (result i32))) (type $c0 (cont $f0))
      (type $f1 (func (param i32) (result i32))) (type $c1 (cont $f1))
      (type $f2 (func (result i32))) (type $c2 (cont $f2))
      (global $calls (mut i32) (i32.const 0))
      (func $worker (type $f0)
        (global.set $calls (i32.add (global.get $calls) (i32.const 1)))
        (i32.add (i32.mul (local.get 0) (i32.const 100)) (local.get 1)))
      (elem declare func $worker)
      (func (export "run") (result i32 i32) (local $k (ref null $c2))
        (local.set $k (cont.bind $c1 $c2 (i32.const 22)
          (cont.bind $c0 $c1 (i32.const 11) (cont.new $c0 (ref.func $worker)))))
        (global.get $calls)
        (resume $c2 (local.get $k)))
      (func (export "calls") (result i32) (global.get $calls))
      (func (export "misuse") (result i32) (local $old (ref null $c0))
        (local.set $old (cont.new $c0 (ref.func $worker)))
        (drop (cont.bind $c0 $c1 (i32.const 11) (local.get $old)))
        (resume $c0 (i32.const 11) (i32.const 22) (local.get $old))))"#;
    let bytes = modules(source);
    let engine = Engine::new(Config::default()).unwrap();
    let module = engine.compile(&bytes[0]).unwrap();
    let mut store = Store::new(&engine);
    let instance = Linker::new(&engine)
        .instantiate(&mut store, &module)
        .unwrap();
    assert_eq!(
        call(&mut store, &instance, "run").unwrap(),
        RunOutcome::Returned(vec![Value::I32(0), Value::I32(1122)])
    );
    assert_eq!(
        call(&mut store, &instance, "calls").unwrap(),
        RunOutcome::Returned(vec![Value::I32(1)])
    );
    assert_eq!(
        call(&mut store, &instance, "misuse").unwrap_err().kind,
        ErrorKind::Trap
    );
    assert_eq!(
        call(&mut store, &instance, "calls").unwrap(),
        RunOutcome::Returned(vec![Value::I32(1)])
    );
    store.collect().unwrap();
    assert_eq!(store.continuation_bytes(), 0);
}

#[test]
fn t142_nearest_prompt_and_exception_unwinding_preserve_delimiters() {
    let source = r#"(module
      (type $f (func (result i32))) (type $c (cont $f))
      (type $rf (func (param i32) (result i32))) (type $rc (cont $rf))
      (tag $yield (result i32)) (tag $error)
      (func $leaf (type $f) (suspend $yield))
      (func $inner (type $f) (local $k (ref null $rc))
        (block $nearest (result (ref $rc))
          (resume $c (on $yield $nearest) (cont.new $c (ref.func $leaf)))
          (return))
        (local.set $k)
        (i32.add (i32.const 100) (resume $rc (i32.const 11) (local.get $k))))
      (func $thrower (type $f)
        (block $caught (try_table (catch $error $caught) (throw $error)))
        (suspend $yield))
      (elem declare func $leaf $inner $thrower)
      (func (export "nearest") (result i32)
        (block $outer (result (ref $rc))
          (resume $c (on $yield $outer) (cont.new $c (ref.func $inner)))
          (return))
        (drop) (i32.const 999))
      (func (export "unwind") (result i32) (local $k (ref null $rc))
        (block $outer (result (ref $rc))
          (resume $c (on $yield $outer) (cont.new $c (ref.func $thrower)))
          (return))
        (local.set $k)
        (resume $rc (i32.const 42) (local.get $k))))"#;
    let bytes = modules(source);
    let engine = Engine::new(Config::default()).unwrap();
    let module = engine.compile(&bytes[0]).unwrap();
    let mut store = Store::new(&engine);
    let instance = Linker::new(&engine)
        .instantiate(&mut store, &module)
        .unwrap();
    assert_eq!(
        call(&mut store, &instance, "nearest").unwrap(),
        RunOutcome::Returned(vec![Value::I32(111)])
    );
    assert_eq!(
        call(&mut store, &instance, "unwind").unwrap(),
        RunOutcome::Returned(vec![Value::I32(42)])
    );
    store.collect().unwrap();
    assert_eq!(store.continuation_bytes(), 0);
}

#[test]
fn t115_constructor_operand_survives_collection_at_host_safepoint() {
    let source = r#"(module
      (import "env" "collect" (func $collect (result i32)))
      (type $child (struct (field i32)))
      (rec
        (type $object (descriptor $descriptor) (struct (field (ref $child))))
        (type $descriptor (describes $object) (struct (field i32))))
      (func (export "run") (result i32)
        (struct.get $child 0 (struct.get $object 0
          (struct.new_desc $object (struct.new $child (i32.const 77))
            (struct.new $descriptor (call $collect)))))))"#;
    let bytes = modules(source);
    let engine = Engine::new(Config::default()).unwrap();
    let module = engine.compile(&bytes[0]).unwrap();
    let mut store = Store::new(&engine);
    let count = Arc::new(AtomicUsize::new(0));
    let observed = count.clone();
    let collector = store
        .create_host_func_with_caller(
            FuncType::new(vec![], vec![wtime_types::ValType::I32]),
            move |caller, _| {
                // The child is only on the caller's operand stack, not in the host's
                // arguments or guest locals. Descriptor/object allocation follows.
                assert_eq!(caller.collect()?.live, 1);
                observed.fetch_add(1, Ordering::SeqCst);
                Ok(vec![Value::I32(9)])
            },
        )
        .unwrap();
    let mut linker = Linker::new(&engine);
    linker
        .define("env", "collect", External::Func(collector))
        .unwrap();
    let instance = linker.instantiate(&mut store, &module).unwrap();
    assert_eq!(
        call(&mut store, &instance, "run").unwrap(),
        RunOutcome::Returned(vec![Value::I32(77)])
    );
    assert_eq!(count.load(Ordering::SeqCst), 1);
    assert_eq!(store.collect().unwrap().reclaimed, 3);
}

#[test]
fn t146_cross_module_suspension_preserves_nominal_context_and_exactness() {
    let bytes = modules(
        r#"
      (module
        (type $padding (array (mut i64)))
        (type $object (struct (field i32)))
        (tag (export "yield") (result (ref $object))))
      (module
        (type $object (struct (field i32)))
        (type $result (func (result (ref $object))))
        (type $exact-result (func (result (ref (exact $object)))))
        (type $resume-func (func (param (ref $object)) (result (ref $object))))
        (type $resume-cont (cont $resume-func))
        (import "provider" "yield" (tag $yield (result (ref $object))))
        (func (export "run") (type $result) (suspend $yield))
        (func (export "resume") (param (ref $resume-cont)) (result i32)
          (struct.get $object 0
            (resume $resume-cont (struct.new $object (i32.const 77)) (local.get 0)))))
    "#,
    );
    let engine = Engine::new(Config::default()).unwrap();
    let provider = engine.compile(&bytes[0]).unwrap();
    let consumer = engine.compile(&bytes[1]).unwrap();
    let mut store = Store::new(&engine);
    let provider_instance = Linker::new(&engine)
        .instantiate(&mut store, &provider)
        .unwrap();
    let mut linker = Linker::new(&engine);
    linker
        .define(
            "provider",
            "yield",
            provider_instance.export(&store, "yield").unwrap(),
        )
        .unwrap();
    let instance = linker.instantiate(&mut store, &consumer).unwrap();
    let outcome = call(&mut store, &instance, "run").unwrap();
    assert!(matches!(outcome, RunOutcome::Suspended { .. }));
    let accepted = outcome.clone();
    let host = store
        .create_module_host_func(&consumer, TypeIdx(1), move |_, _| Ok(accepted.clone()))
        .unwrap();
    assert!(matches!(
        store.invoke(host, &[]).unwrap(),
        RunOutcome::Suspended { .. }
    ));
    let retained = outcome.clone();
    let host = store
        .create_module_host_func(&consumer, TypeIdx(2), move |_, _| Ok(outcome.clone()))
        .unwrap();
    assert_eq!(store.invoke(host, &[]).unwrap_err().kind, ErrorKind::Host);
    let RunOutcome::Suspended { continuation, .. } = retained else {
        panic!()
    };
    let External::Func(resume) = instance.export(&store, "resume").unwrap() else {
        panic!()
    };
    assert_eq!(
        store
            .invoke(
                resume,
                &[Value::Ref(wtime_runtime::RefValue::Gc(continuation))]
            )
            .unwrap(),
        RunOutcome::Returned(vec![Value::I32(77)])
    );
}
